-- SQLite schema generated by the original Flask-SQLAlchemy application.
CREATE TABLE device_status (
	id VARCHAR(1024) NOT NULL,
	show_name VARCHAR(1024) NOT NULL,
	"using" BOOLEAN,
	status TEXT,
	fields JSON NOT NULL,
	last_updated FLOAT NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (id)
);

CREATE TABLE main (
	id INTEGER NOT NULL,
	status INTEGER NOT NULL,
	private_mode BOOLEAN NOT NULL,
	last_updated FLOAT NOT NULL,
	PRIMARY KEY (id)
);

CREATE TABLE plugin (
	id VARCHAR(1024) NOT NULL,
	data JSON NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (id)
);
